using System;
using UnityEngine;

namespace Game.Levels
{
    /// <summary>All levels in play order, plus the Free Flight setup (generated by LevelBuilder).</summary>
    [CreateAssetMenu(menuName = "Game/Configs/Level Catalog", fileName = "LevelCatalog")]
    public sealed class LevelCatalog : ScriptableObject
    {
        [SerializeField] private LevelConfig[] _levels = Array.Empty<LevelConfig>();
        [SerializeField] private LevelConfig _freeFlight;

        public int Count => _levels.Length;
        public LevelConfig FreeFlight => _freeFlight;

        /// <summary>The level at index, or Free Flight for GameProgress.FreeFlight / out of range.</summary>
        public LevelConfig Get(int index) => index >= 0 && index < _levels.Length ? _levels[index] : _freeFlight;

#if UNITY_EDITOR
        public void Define(LevelConfig[] levels, LevelConfig freeFlight)
        {
            _levels = levels;
            _freeFlight = freeFlight;
        }
#endif
    }
}
